    def isPossible(self, n: int, edges: List[List[int]]) -> bool:
        neighbors = [set() for _ in range(n)]
        for edge in edges:
            a, b = edge
            a -= 1
            b -= 1
            if a == b:
                continue
            neighbors[a].add(b)
            neighbors[b].add(a)

        odd_nodes = [i for i in range(n) if len(neighbors[i]) % 2 == 1]
        if len(odd_nodes) == 0:
            return True
        if len(odd_nodes) % 2 == 1:
            return False

        if len(odd_nodes) == 2:
            u, v = odd_nodes
            if u not in neighbors[v]:
                return True
            for x in range(n):
                if x in {u, v}:
                    continue
                if u not in neighbors[x] and v not in neighbors[x]:
                    return True
            return False

        if len(odd_nodes) == 4:
            a, b, c, d = odd_nodes
            pairs = [((a, b), (c, d)), ((a, c), (b, d)), ((a, d), (b, c))]
            for (u1, v1), (u2, v2) in pairs:
                if u1 not in neighbors[v1] and u2 not in neighbors[v2]:
                    return True
            return False

        return False

