class CodeReviewCandidate:
    def minimumTotalCost(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums1)
        a = tuple(nums1)
        b = tuple(nums2)

        from functools import lru_cache

        @lru_cache(None)
        def dfs(state_a: tuple, state_b: tuple) -> int:
            if all(state_a[i] != state_b[i] for i in range(n)):
                return 0

            best = float('inf')
            for i in range(n):
                if state_a[i] == state_b[i]:
                    for j in range(n):
                        if i == j:
                            continue
                        new_a = list(state_a)
                        new_a[i], new_a[j] = new_a[j], new_a[i]
                        candidate = (i + j) + dfs(tuple(new_a), state_b)
                        if candidate < best:
                            best = candidate
                    break

            return best if best != float('inf') else -1

        return dfs(a, b)

