class CodeReviewCandidate:
    def isTransformable(self, s: str, t: str) -> bool:
        # Sorting substrings preserves the multiset of characters.
        # Therefore strings with different lengths or character counts
        # can never be transformed into one another.
        if len(s) != len(t) or Counter(s) != Counter(t):
            return False

        indexes = collections.defaultdict(collections.deque)

        for index, character in enumerate(s):
            indexes[int(character)].append(index)

        for character in t:
            character_designation = int(character)

            if character_designation not in indexes:
                return False

            for lesser_character in range(character_designation):
                if (
                    indexes[lesser_character]
                    and indexes[lesser_character][0]
                    < indexes[character_designation][0]
                ):
                    return False

            indexes[character_designation].popleft()

            if not indexes[character_designation]:
                indexes.pop(character_designation)

        return True

